// Ordinary page navigation keeps forms usable without a JavaScript framework.
document.addEventListener("submit", (event) => {
  const message = event.target.dataset.confirm;
  if (message && !window.confirm(message)) event.preventDefault();
});

document.addEventListener("change", (event) => {
  const form = event.target.closest("form[data-auto-submit]");
  if (form) form.requestSubmit();
});

document.querySelectorAll("[data-question-form]").forEach((form) => {
  const rows = form.querySelector("[data-option-rows]");
  const template = form.querySelector("[data-option-template]");
  form.querySelector("[data-add-option]").addEventListener("click", () => {
    const index = rows.querySelectorAll("[data-option-row]").length;
    const html = template.innerHTML.replaceAll("ROW_INDEX", index).replaceAll("ROW_NUMBER", index + 1);
    rows.insertAdjacentHTML("beforeend", html);
    rows.lastElementChild.querySelector('input[type="text"]').focus();
  });
});

// Preview has no requests, cookies, localStorage, or sessionStorage. A page load
// starts a fresh attempt; only the question snapshot comes from the server.
const preview = document.querySelector("[data-preview]");
if (preview) {
  const questions = JSON.parse(document.getElementById("preview-data").textContent);
  const content = preview.querySelector("[data-preview-content]");
  let current = 0;
  let score = 0;

  function element(tag, className, text) {
    const node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined) node.textContent = text;
    return node;
  }

  function letter(index) {
    let result = "";
    do {
      result = String.fromCharCode(65 + index % 26) + result;
      index = Math.floor(index / 26) - 1;
    } while (index >= 0);
    return result;
  }

  function focusHeading() {
    const heading = content.querySelector("h1");
    heading.tabIndex = -1;
    heading.focus();
  }

  function showScore() {
    content.replaceChildren(
      element("div", "play-question__num", "Quiz complete"),
      element("h1", "play-title preview-score", `Score: ${score}/${questions.length}`),
      element("p", "play-lead", "That's a wrap! Try again or head back to your quiz.")
    );
    focusHeading();
  }

  function showQuestion(focus = false) {
    content.replaceChildren();
    if (!questions.length) {
      content.append(
        element("h1", "play-question__body", "No active questions"),
        element("p", "play-lead", "Add or activate a question in your quiz to try the preview.")
      );
      if (focus) focusHeading();
      return;
    }

    const question = questions[current];
    let answered = false;
    const options = element("div", "play-options");
    const feedback = element("div", "preview-feedback");
    feedback.setAttribute("aria-live", "polite");
    feedback.setAttribute("aria-atomic", "true");
    const navigation = element("div", "buttons preview-navigation");

    question.options.forEach((option, index) => {
      const button = element("button", "play-option");
      button.type = "button";
      button.setAttribute("aria-label", option.text);
      const badge = element("span", "play-option__letter", letter(index));
      badge.setAttribute("aria-hidden", "true");
      button.append(badge, element("span", "play-option__title", option.text));
      button.addEventListener("click", () => {
        if (answered) return;
        answered = true;
        if (option.correct) score += 1;
        options.classList.add("is-locked", "is-revealed");
        Array.from(options.children).forEach((choice, i) => {
          choice.disabled = true;
          choice.classList.toggle("is-picked", i === index);
          if (questions[current].options[i].correct) {
            choice.classList.add("is-correct");
            choice.append(element("span", "play-option__mark", "✓ Correct"));
          }
        });
        feedback.append(
          element("div", `play-status ${option.correct ? "play-status--correct" : "play-status--wrong"}`, option.correct ? "Correct!" : "Wrong!"),
          element("p", "preview-answer", `Correct options: ${question.options.filter((item) => item.correct).map((item) => item.text).join(", ")}`)
        );
        const next = element("button", "btn btn--pink", current === questions.length - 1 ? "See score" : "Next question");
        next.type = "button";
        next.addEventListener("click", () => {
          current += 1;
          if (current === questions.length) showScore();
          else showQuestion(true);
        }, { once: true });
        navigation.append(next);
        next.focus();
      });
      options.append(button);
    });

    content.append(
      element("div", "play-question__num", `Question ${current + 1} of ${questions.length}`),
      element("h1", "play-question__body", question.text),
      options, feedback, navigation
    );
    if (focus) focusHeading();
  }

  preview.querySelector("[data-start-over]").addEventListener("click", () => {
    current = 0;
    score = 0;
    showQuestion(true);
  });
  showQuestion();
}
